  "。默认示例保持白色 Light 和小圆角。": ". L'échantillon par défaut conserve la lumière blanche et les petits coins arrondis.",
  "。涉及 button、input、select、form、table、nav、aside 等原生语义时，应优先采用属性形式，让键盘、表单提交、浏览器校验和辅助技术继续使用原生行为。": ". En ce qui concerne la sémantique native telle que bouton, saisie, sélection, formulaire, tableau, navigation, côté, etc., la priorité doit être donnée à l'utilisation d'attributs pour permettre aux claviers, aux soumissions de formulaires, à la validation du navigateur et aux technologies d'assistance de continuer à utiliser les comportements natifs.",
  "。所有对象 Schema 都关闭未知字段或显式声明动态值类型。": ". Tous les schémas d'objet désactivent les champs inconnus ou déclarent explicitement des types de valeurs dynamiques.",
  "。它还会透传 className、style、ID、ARIA 与其他原生属性；": ". Il transmet également de manière transparente le nom de classe, le style, l'ID, l'ARIA et d'autres attributs natifs ;",
  "。它验证 AngularJS": ". Il valide AngularJS",
  "。它逐项映射全部 506 个 CSS 组件和 66 种 DOM 行为，同时提供 538 个根运行时导出、21 个 TypeScript 类型导出、29 个包入口与 28 个组件 CSS 包代理。": ". Il mappe les 506 composants CSS et les 66 comportements DOM élément par élément, tout en fournissant 538 exportations d'exécution racine, 21 exportations de type TypeScript, 29 points d'entrée de package et 28 proxys de package CSS de composants.",
  "。它逐项映射全部 506 个 CSS 组件和 66 种 DOM 行为，同时提供 538 个根运行时导出、22 个 TypeScript 类型导出、 29 个公共包入口与 28 个组件 CSS 包代理。": ". Il mappe les 506 composants CSS et les 66 comportements DOM élément par élément, tout en fournissant 538 exportations d'exécution racine, 22 exportations de type TypeScript, 29 points d'entrée de packages publics et 28 proxys de packages CSS de composants.",
  "。未知平台、包或组件会立即失败；输出清单由": ". Les plates-formes, packages ou composants inconnus échouent immédiatement ; le listing de sortie est donné par",
