  "安全区、动态视口、顶部栏、底部导航、Bottom/Action/Filter Sheet、下拉刷新、无限加载、滑动操作、滚轮选择、键盘避让、移动认证与结算、权限和离线状态都有稳定契约，可直接用于移动网页、PWA 和 Tauri/Electron 移动式 WebView。": "Zone de sécurité, port de vue dynamique, barre supérieure, navigation de fond, feuille de fond/action/filtre, tirage à neuf, chargement infini, opération coulissante, sélection des roues, évitement du clavier, authentification et règlement mobiles, permissions et statut hors ligne ont des contrats stables et peuvent être utilisés directement pour les pages Web mobiles, PWA et Tauri/Electron mobile WebView.",
