  "绑定 Electron 安全桥与销毁周期": "Liaison du pont de sécurité et du cycle de destruction Electron",
  "绑定 Tauri 窗口按钮与销毁周期": "Bouton de fenêtre Bind Tauri et cycle de destruction",
  "绑定行为并访问实例": "Comportement du bind et instances d'accès",
  "包裹；容器小于 768px 会独立折叠，不受浏览器窗口宽度干扰。": "Emballage ; Les conteneurs de taille inférieure à 768 px se réduiront indépendamment, quelle que soit la largeur de la fenêtre du navigateur.",
  "包含每一项，适合 AI 和构建工具直接读取。": "Contient chaque article approprié pour la lecture directe par l'IA et construire des outils.",
  "包明确支持 Node.js >=18.18、Chrome/Edge/Firefox 100+、Safari/iOS 15.4+ 和 ESM；主入口及桌面适配器提供条件": "Le package prend explicitement en charge Node.js >=18.18, Chrome/Edge/Firefox 100+, Safari/iOS 15.4+ et ESM ; le portail principal et l'adaptateur de bureau fournissent des conditions",
  "包入口": "Entrée du colis",
  "包入口可在服务端安全导入，全部 506 个组件均经过逐项 SSR，行为只在 Effect 生命周期内初始化；服务端标记 Hydration 不产生 recoverable error，并兼容 StrictMode。Tauri 与 Electron 分别使用": "L'entrée du package peut être importée en toute sécurité côté serveur. Les 506 composants sont passés par le SSR élément par élément et le comportement n'est initialisé que pendant le cycle de vie de l'effet ; la marque côté serveur Hydration ne génère pas d’erreurs récupérables et est compatible avec StrictMode. Tauri et Electron sont utilisés respectivement",
  "保持兼容，可继续作为业务级壳使用。": "Reste compatible et peut continuer à être utilisé comme shell de niveau métier.",
  "保持为外部 peer dependency，不会把它打进 Gardener 产物，也不会掩盖框架级风险。新项目优先选择 Vue、React 或框架无关入口；存量项目必须同时执行输入净化、CSP、资源白名单、桌面桥最小授权和迁移计划。完整要求见": "Conservez-le en tant que dépendance externe, ce qui ne l'intègre pas dans le produit Gardener et ne couvre pas les risques au niveau du framework. Les nouveaux projets sont prioritaires pour choisir des entrées Vue, React ou indépendantes du framework ; les projets existants doivent également mettre en œuvre la désinfection des entrées, le CSP, la liste blanche des ressources, l'autorisation minimale du pont de bureau et le plan de migration. Pour connaître les exigences complètes, voir",
  "保存": "Enregistrer",
  "保存草稿": "Enregistrer l'ébauche",
  "保存成功": "Enregistré avec succès",
  "保存每次正式构建的 raw、gzip、Brotli、压缩比例及 npm 包体积结果。": "Enregistrer les résultats bruts, gzip, Brotli, le rapport de compression et le volume de paquets npm de chaque construction officielle.",
  "保存前可以通过预览检查所有设备宽度。": "Toutes les largeurs de l'appareil peuvent être vérifiées par prévisualisation avant d'enregistrer.",
  "保存筛选、排序和列配置": "Enregistrement des filtres, tri et configuration des colonnes",
  "保护。": "Protection.",
  "保护按钮、链接与输入": "Protéger les boutons, les liens et les entrées",
  "保护账号": "Protéger le compte",
  "保留 AngularJS 原生表单模型或桥接自定义组件值": "Préserver les valeurs du modèle de formulaire natif AngularJS ou des composants personnalisés du pont",
  "保留 Gardener 类、属性、children 与 Ref": "Conserver la classe Gardener, les propriétés, les enfants et Ref",
  "保留 Gardener 类、属性与插槽": "Préserver la classe, les propriétés et les fentes Gardener",
  "保留空轨位置，适合固定卡槽；min / gap": "Gardez la position de rail vide, adapté pour la fixation de la fente de la carte; min / trou",
  "报告与发票": "Rapports et factures",
  "暴露 beforeapproval、beforeclose、beforefilepicker、beforeopen、beforepromptstop、beforepromptsubmit、beforetabclose 7 个必须在 JS/.NET 异步边界前同步阻止的守卫事件。行为成员与事件 detail 契约可从": "Exposé beforeapproval, beforeclose, beforefilepicker, beforeopen, beforepromptstop, beforepromptsubmit, beforetabclose 7 événements de garde qui doivent être bloqués de manière synchrone avant les limites asynchrones JS/.NET. Les membres comportementaux et les contrats détaillés de l'événement sont disponibles auprès de",
  "暴露全部 75 个事件，": "Exposer les 75 événements,",
  "本节是给最终用户使用的 AI 产品 UI；后文": "Cette section est pour l'interface utilisateur produit AI pour les utilisateurs finaux; le texte suivant",
