  "标签、按钮、元数据自动换行；gap / align / justify": "Étiquettes, boutons, enveloppe de métadonnées; trou / aligner / justifier",
  "标签、分段/选择、全屏对话框、Snackbar": "Tags, Segmentation/Sélection, Boîte de dialogue Plein écran, Snackbar",
  "标签、分栏、Dock、检查器和状态栏都保持高密度、小圆角和完整键盘路径。": "Les étiquettes, les colonnes, le quai, l'inspecteur et la barre d'état maintiennent tous une densité élevée, de petits coins arrondis et des chemins de clavier complets.",
  "标签搜索、创建与多选": "Recherche d'étiquettes, création et sélection multiple",
  "标题": "Titre",
  "标题和操作分居两端并可换行；gap / align": "Le titre et l'action sont séparés aux deux extrémités et peuvent enrouler; trou / aligner",
  "标题栏、活动栏、工作台、检查器与状态栏。": "Barre de titre, barre d'activité, banc de travail, inspecteur et barre de statut.",
  "标准发布": "Publication standard",
  "标准页面宽度与自适应左右留白。": "Largeur standard de la page et marges adaptatives gauche et droite.",
