  "表达 Dirty、Saving、Saved 和 Error，并支持延迟保存及立即保存。": "Exprime Dirty, Saving, Saved et Error, et prend en charge les sauvegardes différées et immédiates.",
  "表单、导航、浮层、数据、媒体、商业、通信、法律、工作流和 Dashboard 均有稳定结构与状态约定。": "Les formulaires, la navigation, les superpositions, les données, les médias, les affaires, les communications, le droit, le flux de travail et le tableau de bord ont tous des structures stables et des conventions d'État.",
  "表单不再从一堆 Input 开始": "Les formulaires ne commencent plus par un tas d'entrées",
  "表单传统组合": "Forme de combinaison traditionnelle",
