  "并排": "côte à côte",
  "并排/统一差异及增删语义": "Différences latérales/unifiées et sémantique d'ajout et de suppression",
  "不强制裁切的通用比例盒": "Boîte proportionnelle universelle sans coupe forcée",
  "不是缩小桌面，而是完整的移动应用层": "Pas un bureau plus petit, mais une couche d'application mobile complète",
  "不要再为下一张页面重新发明基础设施。": "Arrêtez de réinventer l'infrastructure pour la page suivante.",
  "不要在 Renderer 开启 Node Integration，也不要向页面暴露任意 IPC。适配器只接受 minimize、maximize、close、drag 白名单动作。": "Ne pas activer l'intégration des nœuds dans le soumissionnaire et n'exposer aucune CIB à la page. L'adaptateur accepte seulement de minimiser, maximiser, fermer et faire glisser les actions de la liste blanche.",
  "不遮挡内容的补充优先使用 Help Text、Inline Hint 或 Tip；必须绑定控件时使用 Tooltip；包含链接和操作时使用 Help Popover；跨步骤教学使用 Tour。不要把重要错误或必须阅读的法律信息藏进悬浮层。": "Utilisez le texte d'aide, le conseil en ligne ou le conseil pour du contenu supplémentaire qui ne bloque pas le contenu; utilisez Tooltip lorsque les contrôles doivent être liés; utilisez Help Popover lorsque vous incluez des liens et des opérations; utilisez Tour pour l'enseignement en plusieurs étapes. Ne cachez pas les erreurs importantes ou lisez les informations légales dans une couche flottante.",
  "布局": "Disposition",
  "布局、表单、导航、数据、内容、账号、商业、移动、桌面和 AI 均可独立引入。": "La disposition, les formulaires, la navigation, les données, le contenu, les comptes, le commerce, le mobile, le bureau et l'IA peuvent tous être introduits indépendamment.",
  "布局使用逻辑属性，组件覆盖 RTL 下的动画方向与箭头。": "La disposition utilise des propriétés logiques et les composants remplacent la direction d'animation et les flèches sous RTL.",
