  "初始化根节点自身及其后代的全部行为。": "Initialise tout le comportement du nœud racine lui-même et de ses descendants.",
  "处理复杂 CustomEvent。值会转换为 .NET 字符串、布尔、数字、数组或字典；DOM、File、BigInt、函数和循环引用会安全序列化。": "Gestion des CustomEvents complexes. Les valeurs sont converties en chaînes .NET, booléennes, nombres, tableaux ou dictionnaires ; DOM, File, BigInt, fonctions et références circulaires sont sérialisés en toute sécurité.",
  "处理拖入深度、键盘激活和真实文件事件；": "Gérer la profondeur de glissement, l'activation du clavier et les événements de fichiers réels ;",
  "处理原生 input/change，": "Gérer les entrées/modifications natives,",
  "触控 · 安全区 · 双栏": "Toucher · Zone de sécurité · Double colonne",
  "触控目标在 Coarse Pointer 环境至少 44px；所有手势组件保留按钮或键盘路径。": "Les cibles tactiles dans les environnements Coarse Pointer mesurent au moins 44 px ; tous les composants gestuels conservent les chemins des boutons ou du clavier.",
