  "窗口 Chrome、导航、编辑区、状态区和宿主桥接各有独立契约。": "Fenêtre Chrome, navigation, zone d'édition, zone d'état, et pont hôte chacun ont des contrats indépendants.",
  "创建标准内部部件，避免破坏 CSS 和行为选择器契约。": "Créez des éléments internes standard pour éviter de rompre les contrats CSS et de sélection de comportement.",
