  "次要操作": "Opération secondaire",
  "从": "De",
  "从 52 个成品结构中选择最接近的页面骨架。": "Sélectionnez le squelette de la page la plus proche parmi 52 structures finies.",
  "从第一次登录，到每一次安全审计": "De la première connexion à chaque vérification de sécurité",
  "从第一行 CSS 到几十万套 AI 生成模板，这里描述 Gardener 的稳定接口、选择顺序、环境矩阵和交付边界。": "De la première ligne de CSS à des centaines de milliers d'ensembles de modèles générés par l'IA, voici une description de l'interface stable de Gardener, de l'ordre de sélection, de la matrice d'environnement et des limites de livraison.",
  "从静态 SSR 到桌面 WebView，使用同一套 Razor 组件": "De la SSR statique au WebView de bureau en utilisant le même ensemble de composants Razor",
  "从看见商品，到交易与退款完成": "De voir le produit à remplir la transaction et le remboursement",
  "从逻辑 inline-start 方向偏移": "Débranchement de la direction logique de démarrage en ligne",
  "从企业站主导航到 CMS 树，从移动底栏到 Electron Activity Bar，从右键菜单到 Scrollspy，38 种稳定模式让 AI 直接按意图选择。": "De la navigation du propriétaire du site d'entreprise à l'arborescence CMS, de la barre mobile inférieure à la barre d'activité Electron, du menu à droite au défilement, 38 modes stables permettent à l'IA de sélectionner directement selon l'intention.",
  "从上传一个文件，到完成整套内容生产": "Du téléchargement d'un fichier à la production complète du contenu",
  "从上下主区、左右栏到 Holy Grail、Master / Detail、Dock、可调分栏和全屏工作区，Web、移动端与 Tauri / Electron 直接选用，不必临时编写页面级布局 CSS。": "Des zones principales supérieures et inférieures, des colonnes de gauche et de droite à Saint Graal, Master / Detail, Dock, des colonnes réglables et un espace de travail plein écran, web, terminaux mobiles et Tauri / Electron peuvent être directement sélectionnés sans avoir à écrire temporairement la mise en page CSS.",
  "从事件载荷取值": "Obtenez la valeur de la charge utile de l'événement",
  "从完整系统开始。": "Commencez par un système complet.",
