  "粗体": "gras",
  "促销列表": "Liste de promotion",
  "存在配方时，不从零拼装高复用页面。": "Les pages à haute réutilisation ne sont pas assemblées à partir de zéro lorsque des recettes existent.",
  "打开": "Ouvrir",
