  "打印": "Imprimer",
  "打印端使用": "Utilisation côté impression",
  "打印时 Reel、Scroll Area、Scroll Snap、Masonry、Imposter、Overlay 和 Sticky Region 自动展平，避免内容被裁掉。": "Les bobines, la zone de défilement, le snap de défilement, la maçonnerie, l'ampoule, la superposition et la région collante sont automatiquement aplaties lors de l'impression pour éviter que le contenu ne soit recadré.",
  "打印时固定、粘性、全屏和分栏被展平成普通文档流；分隔手柄自动隐藏。": "Les fichiers fixes, collants, plein écran et en colonnes sont aplatis dans le flux de documents normal lors de l'impression ; les poignées de séparation sont automatiquement masquées.",
  "打印时交互栏、筛选、加载遮罩和浮动按钮隐藏；页头和结果页展平，错误说明与请求编号仍保留。": "La barre d'interaction, le filtre, le masque de chargement et le bouton flottant sont cachés lors de l'impression; l'en-tête et la page de résultat sont aplatis, et la description d'erreur et le numéro de requête sont toujours conservés.",
  "打印时隐藏窗口 Chrome、活动栏、状态栏、工具栏、Bottom Panel 和所有浮层，展开主内容、Dock 与 Inspector，避免裁切。": "Cacher la fenêtre Chrome, barre d'activité, barre d'état, barre d'outils, panneau inférieur et toutes les couches flottantes lors de l'impression, étendre le contenu principal, Dock et Inspecteur pour éviter le recadrage.",
  "打印隐藏 Tooltip、Popover、Tour、Spotlight、Hotspot 与反馈动作，保留 Tip、Callout、Note 和排错正文。": "Imprimer et cacher Tooltip, Popover, Tour, Spotlight, Hotspot et actions de rétroaction, conserver Conseil, Callout, Note et le texte de dépannage.",
  "打印与文档输出": "Impression et sortie de documents",
