  "定义高频页面根类、所有必要部件、适用平台、行为、桌面适配器和用途。它不是截图模板，而是可换主题、可响应、可继续组合的稳定结构。以下展开项保留每个配方的全部字段。": "Définit la classe racine de page haute fréquence, tous les composants nécessaires, les plateformes applicables, les comportements, les adaptateurs de bureau et l'utilisation. Ce n'est pas un modèle de capture d'écran, mais une structure stable qui peut être changée en thèmes, est réactive et peut être continuellement combinée. L'expansion suivante conserve tous les champs pour chaque recette.",
