  "对比度、包边界、导出和版本": "Contraste, limites des paquets, exportation et version",
  "对话": "Dialogue",
  "对话、Composer 与流式回答之外，还需要推理摘要、工具调用和批准、多 Agent 编排、来源引用、Artifact、上下文记忆、Token/费用、语音、权限、隐私、安全复核与反馈评估。Gardener 将整条 AI 任务链做成可直接复用的32种模式。": "En plus du dialogue, Compositeur et réponses en streaming, résumé de raisonnement, invocation et approbation d'outils, orchestration multi-agents, citation source, Artifact, mémoire contextuelle, Token/fee, voix, permissions, vie privée, examen de sécurité et évaluation de la rétroaction sont également nécessaires. Gardener fait de toute la chaîne de tâches AI en 32 modes qui peuvent être réutilisés directement.",
