  "分栏、命令、菜单、导航、Dock、托盘和 About Dialog": "Colonnes, commandes, menus, navigation, Dock, barre d'état et boîte de dialogue À propos",
  "分栏认证": "Certification en colonne",
  "分栏认证在 704px 以下收敛为单列；卡片在 384px 以下重排 QR、规则与恢复码；底部操作尊重 Safe Area。": "L'authentification des colonnes converge vers une seule colonne au-dessous de 704px; les cartes sont réaménagées avec le QR, les règles et les codes de récupération au-dessous de 384px; les opérations de fond respectent la zone de sécurité.",
  "分类": "Classement",
