  "可关闭组件自动初始化， 方便由页面级运行时统一接管。显式传入的行为 data attribute 优先于生成默认值。": "L'initialisation automatique des composants peut être désactivée pour faciliter la prise en charge unifiée par le moteur d'exécution au niveau de la page. Le comportement consistant à transmettre explicitement un attribut de données est prioritaire sur la génération d'une valeur par défaut.",
  "可滚动区域应可被键盘聚焦并提供可访问名称；Reduced Motion 会取消原语的平滑滚动。": "Les zones de défilement doivent être focalisées sur le clavier et fournir un nom accessible.",
  "可机器验证": "Vérification de la machine",
  "可切换公共网站、Dashboard、CRM、行业门户与状态中心预览。": "Site public commutable, tableau de bord, CRM, portail industriel et aperçu du centre de statut.",
  "可取消 Before 事件、Approved/Rejected/Cancelled、Reset API": "Annulable avant l'événement, approuvé/rejeté/annulé, réinitialisation de l'API",
  "可取消流程守卫": "Le garde-processus peut être annulé",
  "可使用": "Disponible",
  "可选索引文本": "Texte d'index facultatif",
  "可以跨 32 种页面复用，保证 AI 在换行业时不改变基础语法。": "peut être réutilisé sur 32 types de pages pour garantir que la syntaxe de base de l'IA ne change pas lors d'un changement de secteur.",
  "可用工具类包括": "Les classes d'outils disponibles incluent",
  "可用值": "Valeurs disponibles",
  "可直接测试 App Bar、Bottom Navigation、Swipe Tabs、Swipe Actions、Infinite Load、Action/Filter Sheet 与移动选择器。": "Essais directs de la barre d'application, de la navigation de fond, des onglets de balayage, des actions de balayage, des charges infinies, des feuilles action/filtre et des sélecteurs mobiles.",
  "可直接测试排序、选择、展开、列显隐、搜索、视图切换、移动堆叠表和键盘网格。": "Le tri, la sélection, l'expansion, la visibilité de la colonne, la recherche, la commutation de vue, le déplacement des tables empilées et la grille de clavier peuvent être testés directement.",
  "可直接测试全选、反选、范围选择、Transfer、Picker、Cascader、Saved Choice 和动态 Builder。": "Sélectionner tout, sélection inverse, sélection de la plage, transfert, sélection, Cascader, choix sauvegardé et constructeur dynamique peut être testé directement.",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包实测为 326,076 B raw、50,128 B gzip、26,375 B Brotli；单个": "Lisible directement par l'IA, les générateurs de code et les outils de documentation. La mesure réelle de l'emballage entièrement compressé est de 326 064 B raw, 50 126 B gzip, 26 381 B Brotli ; célibataire",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包实测为 404,104 B raw、59,503 B gzip、29,798 B Brotli；单个": "Lisible directement par l'IA, les générateurs de code et les outils de documentation. La mesure réelle du package entièrement compressé est de 404 094 B raw, 59 499 B gzip, 29 785 B Brotli ; célibataire",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包预算为 328,236 B raw、51,605 B gzip、26,932 B Brotli；单个": "Lisible directement par l'IA, les générateurs de code et les outils de documentation. Le budget pour le package entièrement compressé est de 328 220 B raw, 51 602 B gzip, 26 926 B Brotli ; célibataire",
