  "框架提供焦点样式、减少动效、高对比和 Forced Colors 基础，但语义名称与内容顺序仍由页面作者负责。": "Le cadre fournit une base pour les styles de focus, le mouvement réduit, le contraste élevé et les couleurs forcées, mais la désignation sémantique et l'ordre de contenu restent la responsabilité de l'auteur de la page.",
  "扩展": "Extension",
  "了解发布状态": "Comprendre l'état de la version",
  "类。": ".",
  "类必须出现在“CSS 全量 API”或“工具类”清单；每个组件、运行时和页面配方还必须出现在各自目录。构建校验会逐文件计算 SHA-256，避免目录落后于源码。": "La classe doit apparaître dans la liste CSS Full API ou Tool Classes ; chaque composant, runtime et recette de page doit également apparaître dans leurs répertoires respectifs. La vérification de build calcule SHA-256 fichier par fichier pour éviter que les répertoires ne soient en retard par rapport au code source.",
  "类名": "Nom de la classe",
  "类型，并保留默认语义标签、选择器、状态、部件、行为、平台与无障碍元数据。静态 SSR 阶段直接输出完整 HTML，建立交互连接后才挂载 DOM 行为；参数签名改变会刷新挂载，组件释放时会注销监听器。": "saisissez et conservez les balises sémantiques, les sélecteurs, les états, les widgets, les comportements, les métadonnées de plateforme et d'accessibilité par défaut. La phase SSR statique génère directement du HTML complet et ne monte le comportement DOM qu'après avoir établi une connexion interactive ; les modifications dans les signatures de paramètres actualiseront le montage et l'écouteur sera déconnecté lorsque le composant sera publié.",
  "类型、所有者、校验值和版权": "Type, propriétaire, valeur de contrôle et droit d'auteur",
  "类型安全监听 gardener:* 事件": "Écoute sécuritaire pour jardinier :* événements",
