  "逻辑方向属性": "attribut direction logique",
  "逻辑方向属性覆盖 RTL；Reduced Motion 停止同步脉冲；Forced Colors 为当前 Activity/Tab/Command 提供明确轮廓。": "L'attribut direction logique remplace RTL; Réduction du mouvement arrête les impulsions de synchronisation; Couleurs forcées fournit un aperçu clair de l'activité/tab/command actuelle.",
  "逻辑方向属性支持 RTL；Reduced Motion 关闭位移过渡；Forced Colors 强化选中轮廓；打印自动展平外壳。": "L'attribut de direction logique prend en charge RTL ; Le mouvement réduit désactive les transitions de déplacement ; Les couleurs forcées améliorent les contours sélectionnés ; l'impression aplatit automatiquement les coques.",
