  "没有匹配的组件。": "Aucun composant correspondant.",
  "媒体上叠工具、标注、状态；align / justify / margin": "Outils de recouvrement des médias, annotations, état; aligner / justifier / marge",
  "媒体资产工作台与详情栏": "Barre de travail et de détails des actifs médiatiques",
  "每份自定义构建清单还会为可读 CSS、压缩 CSS、Source Map 和随包复制的 Tauri/Electron 适配器生成 SHA-256 与标准 SRI。接收方无需依赖构建机器，即可逐文件验证交付内容是否完整且未被替换。": "Chaque manifeste de compilation personnalisé génère également SHA-256 et SRI standard pour CSS lisible, CSS compressé, Carte source, et l'adaptateur Tauri/Electron copié avec le paquet. Le destinataire peut vérifier par fichier que la livraison est complète et n'a pas été remplacée, sans compter sur la machine de construction.",
  "每个 CSS 组件都有对应的": "Chaque composant CSS a un correspondant",
  "每个公共组件都能解析到完整所属包，并明确列出连带包含项。": "Chaque composante publique résout le paquet complet auquel elle appartient, avec des inclusions explicites.",
