  "默认、info、success、warning、danger；紧凑技巧": "Défaut, info, succès, avertissement, danger; compétences compactes",
  "默认白色 Surface 与 4px 小圆角；组件只使用主题 Token，可在 42 套主色和所有正交主题轴中复用。": "Surface blanche par défaut avec 4px petits coins arrondis; le composant utilise uniquement des jetons de thème, qui peuvent être réutilisés dans 42 jeux de couleurs principales et tous les axes de thème orthogonale.",
  "默认白色 Surface、1px 边框和 4px 小圆角；阴影仅用于命令面板、窗口切换器和菜单等真实浮层。": "Surface blanche par défaut, bordure 1px et 4px petits coins arrondis; les ombres ne sont utilisées que pour les superpositions réelles telles que les panneaux de commande, les commutateurs de fenêtre et les menus.",
  "默认白色 Surface、1px 边框与 4px 小圆角；大圆角和强阴影不是移动端默认。": "Surface blanche par défaut, bordure 1px et 4px petits coins arrondis; grands coins arrondis et ombres fortes ne sont pas par défaut pour mobile.",
  "默认导入。Gardener 包本身不会读取全局 AngularJS，根入口可安全用于 SSR 工具链分析。": "Importé par défaut. Le package Gardener lui-même ne lit pas AngularJS global et l'entrée racine est sûre pour l'analyse de la chaîne d'outils SSR.",
  "默认风格适合个人、企业、后台和内容站，不预设强烈品牌人格。": "Le style par défaut convient aux particuliers, aux entreprises, aux entreprises et aux stations de contenu, et n'établit pas une forte personnalité de marque.",
  "默认视觉：": "Visualisation par défaut :",
  "默认小圆角，可显式扩展": "Par défaut petits coins arrondis, peuvent être explicitement étendus",
  "默认与整行": "Par défaut par rapport à la ligne entière",
