  "全部模式支持逻辑方向、RTL、Reduced Motion、Forced Colors 和打印；打印时隐藏可变更选择状态的控制，并保留结果摘要。": "La direction logique, RTL, Reduced Motion, Forced Colors et l'impression sont prises en charge dans tous les modes; les commandes qui changent l'état de sélection sont cachées lors de l'impression, et les résumés des résultats sont conservés.",
