  "全选、反选、范围选择、批量工具栏、Transfer、树形与级联选择、人员/组织/资源/媒体选择器、日期时间范围、保存配置及排序/分组构建器均有稳定接口。AI 不必临时拼出复杂后台选择流程。": "Sélectionner tout, sélection inversée, sélection de la plage, barre d'outils par lots, sélection de transfert, de l'arborescence et de la cascade, sélecteur de personnes/organisations/ressources/médias, plage de date, sauvegarde de la configuration et tri/groupe constructeur ont tous des interfaces stables. AI n'a pas à improviser des processus complexes de sélection des moteurs.",
