  "认证结果必须明确 Success、Error、Pending；会话过期要说明未提交数据是否保留，安全事件不能只靠颜色表达。": "Le résultat d'authentification doit être clair Succès, Erreur et En attente; l'expiration de la session doit indiquer si les données non soumises sont conservées et les événements de sécurité ne peuvent pas être exprimés uniquement par la couleur.",
  "任务、时间轴和进度条": "Tâches, échéancier et barres de progression",
