  "仍会如实显示 AngularJS 本体的已知公告；这属于必须隔离、接受或迁移的遗留风险，不能标记为已修复。": "Les avis connus pour l'ontologie AngularJS seront toujours affichés fidèlement ; il s’agit d’un risque hérité qui doit être isolé, accepté ou migré et ne peut pas être marqué comme résolu.",
