  "入口、主题、运行时、组件与配方只能新增；删除必须先经过至少两个次版本的废弃期。": "Les entrées, les thèmes, les runtimes, les composants et les recettes ne peuvent être ajoutés; les suppressions doivent d'abord passer la période d'obsolescence d'au moins deux versions mineures.",
