  "上表列出 12 个主要 CSS/Runtime 入口；预算文件还逐项覆盖 2 个桌面适配器、28 个组件包，共 42 个正式压缩产物，没有使用笼统的共享上限替代单产物检查。": "Le tableau ci-dessus énumère 12 entrées principales CSS/Runtime; le document budgétaire détaille également la couverture de 2 adaptateurs de bureau, 28 paquets de composants et un total de 42 produits officiellement compressés, sans utiliser un plafond général de partage pour remplacer les inspections de produits uniques.",
