  "十一套 Schema 全部采用 JSON Schema 2020-12，并拒绝未知字段：": "Les onze ensembles de schémas utilisent JSON Schema 2020-12, et les champs inconnus sont rejetés:",
  "十一套闭合 Schema、48 个标准 Schema 用例、10 个构建专项用例、66 个运行时单元测试、125 个真实浏览器用例与 24 个结构用例": "Onze ensembles de schémas fermés, 48 cas d'utilisation de schémas standard, 10 cas d'utilisation spécifiques à la construction, 66 tests d'unité d'exécution, 125 cas d'utilisation de navigateurs réels et 24 cas d'utilisation structurelle",
  "时会移除事件并销毁行为实例。": "supprime l'événement et détruit l'instance de comportement.",
