  "实现 CSS 或 Runtime。": "Mettre en œuvre CSS ou Runtime.",
  "使用": "Utilisation",
  "使用 {theme} 主题": "Utiliser le thème {theme}",
  "使用 704px 容器折叠；文件浏览、媒体详情、图片编辑器、文档缩略图、Markdown 双栏和版本对比均有移动布局。": "Utiliser le repli du conteneur de 704 px ; le navigateur de fichiers, les détails des médias, l'éditeur d'images, les vignettes de documents, les doubles colonnes Markdown et la comparaison de versions ont tous des mises en page mobiles.",
  "使用 Ajv 2020-12 执行 48 个标准验证用例，覆盖十份发布/配置文档、未知根字段、十类未知嵌套字段、十类缺失嵌套必填字段、跨 Schema 引用、JavaScript 标识符、SHA-256 格式、基线回归状态和旧组件 Schema 兼容别名；": "Exécution de 48 cas d'utilisation de validation standard à l'aide d'Ajv 2020-12, couvrant dix documents de version/configuration, des champs racine inconnus, dix types de champs imbriqués inconnus, dix types de champs obligatoires imbriqués manquants, des références entre schémas, des identifiants JavaScript, des formats SHA-256, un état de régression de base et des alias compatibles avec les schémas de composants existants ;",
  "使用 gzip level 9 与 Brotli quality 11，对全部 42 个正式压缩产物同时计算 raw、gzip 和 Brotli，并检查全量 CSS、Runtime 的压缩比例，以及": "En utilisant gzip niveau 9 et Brotli qualité 11, calculez simultanément raw, gzip et Brotli pour les 42 produits de compression officiels et vérifiez le taux de compression du CSS complet, du Runtime et",
  "使用 Node.js 内置测试运行器和 Happy DOM，对公共清单中的全部 66 种行为逐项双向比对真实实例成员，并验证初始化、幂等性、销毁和重新初始化；同时覆盖 MutationObserver 的动态节点、动态属性、子树移除、作用域销毁、多行为共存、全局销毁和初始化事件冒泡。": "Utilisez Node.js intégré coureur de test et Happy DOM pour comparer bidirectionnellement les membres de l'instance réelle pour les 66 comportements de la liste publique, et vérifier l'initialisation, l'idempotence, la destruction et la réinitialisation; tout en couvrant les nœuds dynamiques de MutationObserver, les attributs dynamiques, l'enlèvement des sous-arbres, la destruction de la portée, la coexistence multi-comportement, la destruction globale et l'initialisation événement bouillonnant.",
  "使用 TypeScript 严格模式编译真实消费者，覆盖默认及命名导出、行为工厂、Toast、实例查询和两类桌面桥接。": "Compilez de vrais consommateurs en utilisant le mode strict TypeScript, couvrant les exportations par défaut et nommées, les usines de comportement, les toasts, les requêtes d'instance et deux types de ponts de bureau.",
  "使用场景": "Scénarios d'utilisation",
  "使用企业 SSO": "Utilisation de SSO Enterprise",
  "使用已登记组件填充功能。": "Remplir la fonction de composants enregistrés.",
  "使用预览环境确认内容，再发布到生产环境。": "Utilisez l'environnement de prévisualisation pour confirmer le contenu avant de publier dans l'environnement de production.",
  "始 / 主 / 末": "Début/Main/Fin",
