  "视口小于 768px 时，多栏、Master / Detail 和检查器布局按语义顺序纵向排列；Dock 默认只保留主区，可用": "Lorsque la fenêtre d'affichage est inférieure à 768 px, les dispositions multi-colonnes, Maître/Détail et Inspecteur sont disposées verticalement dans l'ordre sémantique ; le Dock ne conserve que la zone principale par défaut et est disponible",
