  "是 Gardener CSS 1.0.0 的官方 AngularJS 1.x 遗留系统适配层，当前版本为": "est la couche officielle d'adaptation du système AngularJS 1.x pour Gardener CSS 1.0.0, la version actuelle est",
  "是 Gardener CSS 1.0.0 的官方 Razor Class Library，当前版本为": "est la bibliothèque officielle de classe Razor pour Gardener CSS 1.0.0, la version actuelle est",
  "是 Gardener CSS 1.0.0 的官方 React 适配层，当前版本为": "est la couche d'adaptation officielle React de Gardener CSS 1.0.0, la version actuelle est",
  "是 Gardener CSS 1.0.0 的官方 Vue 3 适配层，当前版本为": "est la couche d'adaptation officielle Vue 3 de Gardener CSS 1.0.0, la version actuelle est",
  "是给生成器使用 Gardener 的约束。前者提供界面组件，后者规定选能力、配方、组件和工具类的顺序。": "est une contrainte pour utiliser Gardener sur des générateurs. Le premier fournit des composants d'interface, et le second spécifie l'ordre dans lequel les capacités, recettes, composants et classes d'outils sont sélectionnés.",
  "是公共命名与程序接口的规范清单，完整登记 CSS 层、包入口、主题属性、JavaScript 导出、行为、事件、桌面适配器和兼容字段。": "est une liste canonique d'interfaces publiques de dénomination et de programmation, enregistrant entièrement les couches CSS, les entrées de package, les propriétés de thème, les exportations JavaScript, les comportements, les événements, les adaptateurs de bureau et les champs de compatibilité.",
  "是五个公共区域；": "sont cinq espaces communs ;",
  "是预压缩单文件入口。SSR 导入不访问浏览器全局对象，行为只在组件挂载后初始化，因此可用于服务端渲染与 Hydration。": "est une entrée de fichier unique précompressée. L'importation SSR n'accède pas aux objets globaux du navigateur et le comportement n'est initialisé qu'une fois le composant monté, il peut donc être utilisé pour le rendu côté serveur et l'hydratation.",
  "适合 WebView": "Convient pour WebView",
  "适用场景": "Scénarios applicables",
  "释放监听器、计时器和实例引用。": "Relâchez les auditeurs, les minuteurs et les références d'instance.",
  "收藏": "Collection",
  "收录完整 42 个颜色主题，默认保持白底 Light 与小圆角 small。 5 个作用域服务为": "Contient 42 thèmes de couleurs, avec un fond blanc clair par défaut et de petits coins arrondis. Les 5 services de portée sont",
  "收入": "Recettes",
  "收入上升": "Augmentation des recettes",
  "手机验证": "Vérification des téléphones mobiles",
  "手势、按钮与 Escape 均可操作。": "Gestures, boutons et Escape sont tous disponibles.",
  "手势提示": "Demande de gestuelle",
  "手势只增强效率：Pull Refresh 有刷新按钮路径，Infinite Load 有“加载更多”，Swipe Actions 有 Toggle，Wheel Picker 支持键盘。": "Les gestuelles ne font qu'améliorer l'efficacité : Pull Refresh a un chemin de bouton de rafraîchissement, Infinite Load a \"charger plus\", Swipe Actions a Toggle, et Wheel Picker a un support clavier.",
