  "舒适、标准和紧凑密度": "Confort, densité standard et compacte",
  "输出前校验端点、键盘、焦点、状态、RTL、打印和高对比环境。": "Vérifier les paramètres, clavier, focus, status, RTL, impression et environnements à contraste élevé avant la sortie.",
  "输入发送到 +86 138****6608 的验证码": "Entrez le code de vérification envoyé au +86 138****6608",
  "输入类名、完整选择器、CSS 属性、值或响应条件。为避免一次渲染 11,498 项，至少输入两个字符后分批显示，每次 100 项；输入": "Saisissez un nom de classe, un sélecteur complet, une propriété CSS, une valeur ou une condition de réponse. Pour éviter d'afficher 11 498 éléments à la fois, saisissez au moins deux caractères avant d'afficher par lots de 100 éléments à la fois ; entrer",
  "输入命令": "Saisissez la commande",
  "输入命令或文件名": "Saisissez la commande ou le nom du fichier",
  "属性": "Propriétés",
  "属性 / 触发": "Propriétés/Déclencheur",
  "属性、样式、审计、上下文信息": "Propriétés, styles, vérification, information contextuelle",
  "属性的真实源码命中，将 506 个组件解析到一个或多个完整所属包，而不是截取单个选择器，因此伪类、状态、动画、子部件、容器查询和依赖规则不会丢失。": "Le code source réel correspond aux propriétés, résolvant 506 composants en un ou plusieurs packages d'appartenance complets au lieu de tronquer les sélecteurs individuels, de sorte que les pseudo-classes, états, animations, sous-parties, requêtes de conteneur et règles de dépendance ne soient pas perdus.",
  "术语、缩写与行业概念解释入口": "Terminologie, abréviations et portail d'explication du concept industriel",
