  "搜索名称、类别、选择器、部件、状态或平台": "Nom, catégorie, sélecteur, partie, statut ou plateforme de recherche",
  "搜索内容": "Contenu de la recherche",
  "搜索全部 CSS 接口": "Recherche dans toutes les interfaces CSS",
  "搜索完整工具类清单": "Recherche dans la liste complète des outils",
  "搜索文件": "Fichiers de recherche",
  "搜索页面或内容": "Page de recherche ou contenu",
  "搜索组件": "Composante de recherche",
  "缩进层级、父子行展开": "Niveau d'identification, expansion de la ligne parent-enfant",
  "缩略图、名称、属性和快捷动作": "Thumbnails, noms, propriétés et actions rapides",
  "缩略图网格与媒体多选": "Grille de vignettes et sélection multiple des médias",
  "所有 32 模式均进入组件 Manifest 和动态组件目录；CSS 源码完整 API 也会列出模块、选择器、变量和状态。": "Tous les 32 modes entrent dans les manifestes de composants et les répertoires de composants dynamiques; l'API complète de source CSS énumère également les modules, les sélecteurs, les variables et l'état.",
  "所有结构采用逻辑方向属性并支持 RTL；Forced Colors 提供选择轮廓；打印隐藏数据操作，展开详情和层级行，并移除滚动裁切。": "Toutes les structures adoptent des attributs de direction logiques et prennent en charge RTL; Forced Colors fournit des contours de sélection; imprime des opérations de données cachées, élargit les lignes de détail et de hiérarchie, et supprime le découpage par défilement.",
  "所有开始、结束和操作对齐使用逻辑方向；Floating Action Bar、Back to Top 同时读取设备安全区。": "Tous les alignements de début, de fin et d'action utilisent la direction logique; Floating Action Bar, Back to Top lit également la zone de sécurité de l'appareil.",
  "所有模式覆盖键盘、RTL、Reduced Motion、Forced Colors 与打印；移动结算尊重 Safe Area，打印隐藏购买动作并保留订单、发票和税费信息。": "Tous les modes couvrent le clavier, le RTL, le mouvement réduit, les couleurs forcées et l'impression; la facturation mobile respecte la zone de sécurité, l'impression cache les actions d'achat et conserve les informations sur la commande, la facture et la taxe.",
  "所有模式使用白色 Surface、1px 边框和4px小圆角；在 960/704/512px 容器宽度下折叠 Artifact、Sidebar 与双列模式，并覆盖 RTL、Forced Colors 和打印。": "Utiliser la surface blanche, la bordure 1px et les petits coins arrondis 4px dans tous les modes; effondrer les modes Artifact, Sidebar et Dual Column à 960/704/512px largeur du conteneur, et remplacer RTL, Couleurs forcées et Imprimer.",
  "所有模式使用逻辑方向并覆盖 RTL、Reduced Motion、Forced Colors 和打印；打印隐藏上传与编辑动作，展平滚动区并保留正文和修订信息。": "Tous les modes utilisent la direction logique et couvrent RTL, Réduction du mouvement, Couleurs forcées, et Imprimer; Imprime les caches charge et modifie les actions, aplatit la zone de défilement, et préserve les informations de texte et de révision.",
  "所有水平语义使用 inline/start/end；Media Object、Bleed、Imposter、Overlay、Reel 和 Scroll Snap 支持 RTL。": "Toutes les sémantiques horizontales utilisent inline/start/end; Media Object, Bleed, Imposter, Overlay, Reel et Scroll Snap support RTL.",
  "所有图片有符合目的的": "Toutes les images sont adaptées à leur usage",
  "所有样式覆盖 RTL、Reduced Motion、Forced Colors 与打印。打印隐藏密码、Provider、倒计时和敏感操作，只保留必要的安全审计信息。": "Tous les styles couvrent RTL, Mouvement réduit, Couleurs forcées et impression. Imprimer les mots de passe cachés, les fournisseurs, les comptes à rebours et les opérations sensibles, en ne conservant que les informations de vérification de sécurité nécessaires.",
  "所有原生 attributes、DOM 事件和 slots 均透传。组件模板 Ref 统一公开": "Tous les attributs natifs, événements DOM et emplacements sont transmis. Modèle de composant Réf. divulgation unifiée",
  "所有组合使用逻辑方向属性；Input Group、Money、Unit、字段动作和 Sticky Actions 在 RTL 下保持正确首尾关系。": "Toutes les combinaisons utilisent des attributs de direction logiques; le groupe d'entrée, l'argent, l'unité, les actions sur le terrain et les actions collantes maintiennent une relation de tête à queue correcte en vertu de RTL.",
  "锁屏": "Ecran de verrouillage",
  "套餐、版本和能力横向比较": "Comparaison horizontale des paquets, versions et capacités",
  "提供 640px 容器折叠；移动端 Picker Panel 自动成为底部面板，Batch Toolbar 避让安全区。": "Fournit l'effondrement du conteneur 640px; le panneau mobile Picker devient automatiquement le panneau inférieur, et la barre d'outils par lots évite la zone de sécurité.",
  "提供 Unicode 搜索、网格/列表切换、单项选择、方向键、Home、End、Enter 和 Space，并发布选择事件。": "Fournit la recherche Unicode, la commutation grille/liste, la sélection unique, les touches fléchées, Début, Fin, Entrée et Espace, et publie les événements de sélection.",
  "提供传统 12 栅格。两者都使用原生 CSS Grid、逻辑方向和统一断点，不依赖负边距。": "Fournit 12 grilles traditionnelles. Les deux utilisent une grille CSS native, une direction logique et des points d'arrêt unifiés, et ne s'appuient pas sur des marges négatives.",
  "提供每个页面的端、部件、运行时和用途；": "Fournit le terminal, les widgets, le temps d'exécution et le but de chaque page;",
  "提供适合编辑器、AI 工具和超级 CMS 的固定视口布局。通过": "Fournit une disposition de fenêtre fixe adaptée aux éditeurs, aux outils d'IA et aux super CMS. Passer",
  "提供稳定初始高度，": "Fournit une altitude initiale stable,",
