  "同时提供五档响应式版本": "Aussi disponible en version à cinq vitesses",
  "同时支持元素和属性形式，例如": "Prend en charge les formes d'éléments et d'attributs, par ex.",
  "同一套 CSS，也有完整的 React 组件模型": "Le même ensemble de CSS a également un modèle complet de composants React",
  "同一套语言，覆盖所有端": "La même langue couvre tous les terminaux",
  "同一整页契约可切换企业、个人、医疗、金融或公共服务主题。": "Le même contrat de pleine page peut changer de sujet d'affaires, personnel, médical, financier ou de service public.",
  "统一": "Unification",
  "统一垂直节奏；default、bordered": "Rythme vertical unifié; par défaut, bordé",
  "统一单选/多选、Unicode 搜索、Chip 删除、隐藏字段输出、方向键、Home、End、Enter、Space、Escape 和点击外部关闭。": "Unified single/multiple selection, Unicode search, Chip delete, sortie de champ caché, touches fléchées, Maison, Fin, Entrée, Espace, Échapper et cliquer à l'extérieur pour fermer.",
  "统一的": "unifié",
  "统一工具命令、Ctrl/Command 快捷键、字符与词数；富文本、Markdown、代码和区块编辑器共用协议。": "Unifier les commandes d'outils, les raccourcis Ctrl/Command, le nombre de caractères et de mots; les protocoles communs pour les éditeurs de texte riche, de Markdown, de code et de blocs.",
  "统一命名": "Dénomination unifiée",
  "统一业务实体选择器": "Sélecteur unifié d'entités commerciales",
  "统一页面标题、说明、元数据和操作。": "Unifier les titres, les descriptions, les métadonnées et les actions des pages.",
  "统一页面状态结构": "Unifier la structure d'état des pages",
  "统一页头、工具栏、命令栏、筛选与批量操作，再把 Loading、Empty、Error、403、404、500、离线和维护状态准备完整。AI 生成的页面不再只有“正常数据”这一种情况。": "Unifier l'en-tête de page, la barre d'outils, la barre de commande, le filtrage et les opérations par lots, et préparer l'état de chargement, vide, erreur, 403, 404, 500, hors ligne et de maintenance complètement. Les pages générées par l'IA ne sont plus que des données normales.",
  "头像、缩略图、正文和尾部动作": "Avatar, vignette, actions du corps et de la queue",
