  "完整页面与行业解决方案清单": "Page complète et liste des solutions industrielles",
  "完整映射 506 个组件和 66 种 DOM 行为，提供插件、类型安全组件、指令、Composable、十轴主题 Provider、v-model、SSR 与 Tauri / Electron 适配。每个 CSS 组件都有独立的": "Cartographie complète de 506 composants et 66 comportements DOM, fournissant des plug-ins, des composants de type sécurisé, des directives, Composable, un fournisseur de thèmes à dix axes, un modèle en V, un SSR et une adaptation Tauri/Electron. Chaque composant CSS a le sien",
