  "维护窗口、预计恢复时间和状态页": "Fenêtres d'entretien, temps de récupération estimatif et page d'état",
  "维护队列状态、进度、暂停、重试、移除和汇总计数。": "Conservez l'état de la file d'attente, la progression, les pauses, les tentatives, les suppressions et le nombre global.",
  "维护路径和值；": "Maintenir les chemins et les valeurs ;",
  "为不同终端提供一致而完整的页面体验。": "Fournir une expérience de page cohérente et complète pour différents terminaux.",
