  "先建立租户与身份边界，再组织内容工作流、Dashboard 和门户页面。": "Établir les limites du locataire et de l'identité avant d'organiser les workflows de contenu, les tableaux de bord et les pages portails.",
  "先判断导航范围（全局、局部、层级或页内），再判断方向和终端；Tabs 只切换同一上下文内的视图，Breadcrumb 只表达位置，Pagination 只表达结果集翻页，不应互相替代。": "D'abord déterminer la portée de navigation (globale, locale, hiérarchique ou intrapage), puis déterminer la direction et le terminal; Les onglets ne commutent que les vues dans le même contexte, Fil d'Ariane n'exprime que la position, et Pagination n'exprime que le tour de la page de résultat, et ne devrait pas se remplacer.",
  "先判断数据形态，再判断操作强度。少量静态属性用 Description List 或 Key Value；多记录用 List 或 Table；单元格需要键盘移动和编辑时才使用 Data Grid；层级数据使用 Tree 或 Tree Table；趋势和比较先提供可读数值，再增加图形。": "Déterminer d'abord le formulaire de données, puis l'intensité de fonctionnement. Utiliser la liste de descriptions ou la valeur clé pour un petit nombre d'attributs statiques; utiliser la liste ou la table pour plusieurs enregistrements; utiliser la grille de données uniquement lorsque les cellules nécessitent un mouvement et une modification du clavier; utiliser la table de l'arbre ou de l'arbre pour les données hiérarchiques; les tendances et les comparaisons fournissent d'abord des valeurs lisibles, puis ajouter des graphiques.",
