  "颜色主题": "Thème couleur",
  "颜色主题选择": "Sélection de thème de couleur",
  "颜色主题与中性色、字体、形状、密度、层次、动效、平台和操作系统正交组合。这里始终保持白色浅色界面，只切换品牌主色。": "Les thèmes de couleur sont orthogonalement combinés avec des neutres, des polices, des formes, des densités, des couches, des animations, des plateformes et des systèmes d'exploitation. L'interface blanche et lumineuse est toujours maintenue ici, et seule la couleur principale de la marque est commutée.",
  "颜色主题只负责品牌主色；显示模式与其他主题轴相互独立。本站固定使用 Light，以保持白色文档体验，但框架同时提供 Dark、System 与 High Contrast。": "Le thème de couleur est uniquement responsable de la couleur principale de la marque ; le mode d'affichage est indépendant des autres axes thématiques. Ce site utilise Light pour maintenir une expérience de document blanc, mais le framework fournit également Dark, System et High Contrast.",
