  "摇树、可复现构建、性能预算、npm 封包与 publint": "Tree shake, builds reproductibles, budgétisation des performances, packaging npm et publication",
  "摇树。每个生成组件都保留其默认 HTML 标签的精确属性类型，例如": "Secouez l'arbre. Chaque composant généré conserve le type d'attribut exact de sa balise HTML par défaut, par ex.",
