  "页面不存在": "La page n'existe pas",
  "页面不能只实现正常数据态。至少要明确 Loading、Empty、Error；面向路由和完整应用时还应准备 403、404、500、Offline 和 Maintenance。Gardener 为这些状态提供相同的内容、视觉、详情、操作和帮助部件。": "La page ne peut implémenter que l'état normal des données. Au moins Chargement, Vide et Erreur doit être clair; pour l'acheminement et les applications complètes, 403, 404, 500, Hors ligne, et Maintenance devraient également être préparés. Gardener fournit les mêmes contenus, visuels, détails, actions et aide widgets pour ces états.",
