  "页面管理": "Gestion des pages",
  "页面级 Header、指标、主内容、辅助区和移动折叠已有稳定契约。": "Les en-têtes, les indicateurs, le contenu principal, les zones auxiliaires et les plis mobiles ont des contrats stables.",
