  "页面结构、主题 Token 与交互语义保持一致，各端只增加必要的密度、窗口和安全区适配。": "La structure des pages, le jeton de thème et la sémantique d'interaction sont cohérents, et seules les adaptations nécessaires de la densité, de la fenêtre et de la zone de sécurité sont ajoutées à chaque extrémité.",
