  "营销、个人和内容页使用自然文档滚动；Dashboard 与工作台允许高密度多栏；医疗、金融和政务只是 UI 契约，不替代法规、身份验证、隐私、审计和后端业务规则。": "Les pages marketing, personnelle et de contenu utilisent le défilement naturel des documents; le tableau de bord et le Workbench permettent des colonnes multiples de haute densité; Les services de santé, les finances et le gouvernement ne sont que des contrats d'assurance-chômage et ne remplacent pas les règlements, l'authentification, la protection des renseignements personnels, la vérification et les règles commerciales de soutien.",
