  "用于站点展示和服务通知。": "Pour les avis d'affichage et de service.",
  "用于真实验证 24 / 12、RTL、Container Query 与打印结构。构建检查会逐项验证所有类，而不是只检查几个示例。": "Pour une vérification réelle 24/12, RTL, Container Query et structure d'impression. Les contrôles de build vérifient toutes les classes une par une au lieu de simplement vérifier quelques exemples.",
  "用于直接读取上下文。默认仍是白色 Light 与小圆角，不会自动启用深色主题。": "pour lire directement le contexte. La valeur par défaut est toujours la lumière blanche avec de petits coins arrondis, et le thème sombre ne sera pas automatiquement activé.",
