  "与 Node.js": "avec Node.js",
  "与安全 preload，只暴露 Minimize、Maximize/Restore、Close 等白名单方法；不要开启 Node Integration，也不要把任意 IPC 通道暴露给页面。": "Avec le préchargement de sécurité, exposez uniquement les méthodes de liste blanche telles que Réduire, Maximiser/Restaurer et Fermer ; n'activez pas l'intégration de nœuds et n'exposez aucun canal IPC à la page.",
  "与当前页面或表单上下文绑定的帮助": "Aide liée au contexte actuel de la page ou du formulaire",
  "与工具类的区别：": "Différences par rapport aux classes d'outils :",
  "与可访问名称；Clear Input 同时派发 input/change；Character Count 对 Unicode 字符计数。": "Répartir les entrées/modifications avec un nom accessible ; Effacer l'entrée ; Le nombre de caractères compte les caractères Unicode.",
