  "原生 attributes、事件、children 与": "Attributs natifs, événements, enfants et",
  "原生 input 后备；发出": "Repli d'entrée natif ; émis",
  "原生 input、textarea 和 select 的模型语义仍由 AngularJS 自己管理，适配层不会覆盖": "La sémantique du modèle d'entrée native, de zone de texte et de sélection est toujours gérée par AngularJS lui-même et ne sera pas couverte par la couche d'adaptation.",
  "原生 input/change 自动去重": "Dédoublement automatique des entrées/changements natifs",
  "原生标题栏、窗口按钮、菜单和活动栏只是起点；文档标签、可调分栏、Dock、检查器、命令面板、文件选择、托盘、多窗口、后台任务、更新、权限与崩溃恢复均已有稳定组合，可直接落地 Tauri 与 Electron。": "Les barres de titre, les boutons de fenêtre, les menus et les barres d'activité ne sont que le point de départ; les étiquettes de documents, les colonnes réglables, le dock, l'inspecteur, le panneau de commande, la sélection de fichiers, le plateau, la fenêtre multiple, les tâches de fond, les mises à jour, les permissions et la récupération d'écrasement ont tous été combinés de façon stable et peuvent être directement mis en œuvre dans Tauri et Electron.",
  "原生表单和自定义 Gardener 事件均支持": "Les événements de Gardener natifs et personnalisés sont pris en charge",
  "原生权限请求、网络状态、数据加载、支付、认证和媒体缩放由业务或宿主实现；Gardener 提供稳定视觉、状态、事件与无障碍接口，不伪造结果。": "Les demandes d'autorisation natives, l'état du réseau, le chargement des données, le paiement, l'authentification et l'échelle des médias sont implémentés par l'entreprise ou l'hôte; Gardener fournit une vision stable, l'état, les événements et les interfaces accessibles sans forger de résultats.",
  "原始 JSON 清单": "manifeste JSON brut",
  "原始选择器": "Sélecteur d'origine",
