  "原子式页面": "Formule atomique page",
  "圆形问号入口；hover、focus-visible": "Marque d'interrogation circulaire entrée; vol stationnaire, visible du focus",
  "源码/预览双栏和移动折叠": "Code source/vue double colonne et pliage mobile",
