  "阅读宽度、水平或内容居中；max / gutter": "Largeur de lecture, niveau ou centre de contenu; max/goutte",
  "阅读文档": "Lire la documentation",
  "允许后续 1.x 新增，禁止无迁移路径的删除；在 1.0.0 稳定切点还会反向检查已有入口是否漏记。废弃入口至少保留两个次版本，并只能在新的主版本移除。其闭合结构由": "Autoriser les ajouts 1.x ultérieurs et interdire les suppressions sans chemins de migration ; au seuil stable de 1.0.0, les entrées existantes seront également vérifiées de manière inverse pour voir si elles sont manquantes. Les entrées obsolètes restent dans au moins deux versions mineures et ne peuvent être supprimées que dans une nouvelle version majeure. Sa structure fermée est composée de",
  "允许写入页面模板？": "Permettre l'écriture sur le modèle de page?",
  "允许一次": "Une fois",
  "运行环境": "Environnement d'exploitation",
  "运行时": "Durée",
  "运行时，根据滚动位置显示，点击后平滑返回顶部；Reduced Motion 环境自动使用即时滚动。": "Au moment de l'exécution, l'affichage est basé sur la position de défilement et revient progressivement en haut après avoir cliqué ; l'environnement de mouvement réduit utilise automatiquement le défilement instantané.",
  "运行时、可访问性与环境规则": "Règles sur la durée, l'accessibilité et l'environnement",
  "运行时测试门禁（0.4.0 起）": "Contrôle d'accès à l'essai au moment de l'exécution (depuis 0,40)",
  "运行时框架无关，通过": "Indépendant du framework d'exécution, réussi",
  "运行时事件": "Événements d'exécution",
  "运行时维护状态": "État de la maintenance du temps de fonctionnement",
  "运行时行为新增或改名时，公共 API、示例/补充夹具和逐行为测试必须同步，否则测试会因缺少夹具、实例或成员而失败。": "Lorsqu'un comportement d'exécution est ajouté ou rebaptisé, l'API publique, les appareils échantillon/comportement et les tests par comportement doivent être synchronisés, sinon les tests échoueront en raison des appareils, instances ou membres manquants.",
  "运行时与环境规则": "Règles d'exécution et d'environnement",
  "运行中": "Courant",
  "在 200% 缩放、RTL、Reduced Motion、Forced Colors 下仍可操作。": "Toujours utilisable à l'échelle de 200%, RTL, Mouvement réduit, Couleurs forcées.",
  "在 704px 折叠详情/结算双栏，在 480px 重排行项目与选择卡；视口查询作为没有容器上下文时的兜底。": "Réduire les détails/consulter les doubles colonnes à 704 px, réorganiser les éléments de campagne et sélectionner les cartes à 480 px ; requête de fenêtre d'affichage comme solution de secours lorsqu'il n'y a pas de contexte de conteneur.",
  "在视口或": "Dans la fenêtre ou",
  "在整个": "Partout",
  "增加可运行示例与验证输入。": "Ajouter des exemples et une entrée de validation.",
  "增加数量": "Augmentation de la quantité",
