  "粘性购买栏": "Barre d'achat collante",
  "展开": "Développer",
  "展开任一模块可查看该文件公开的类、Token、状态、数据属性和关键帧。生成型工具模块链接到独立的 11,498 项清单。": "Élargir tout module pour afficher les classes, les jetons, les états, les attributs de données et les images clés exposés par le fichier. Le module outils générateurs se connecte à un inventaire distinct de 11 498 articles.",
  "展开详情": "Agrandir les détails",
