  "账号、租户与身份是不同概念，分别使用 Chooser/Switcher，避免在多组织 CMS 中误操作。": "Le compte, le locataire et l'identité sont des concepts différents. Utilisez Choctor/Switcher respectivement pour éviter les erreurs de fonctionnement dans le CMS multi-organisation.",
