  "支持 Theme、Mode、Neutral、Typography、Shape、Density、Elevation、Motion、Platform、Os 十轴嵌套主题；": "Thème de support, mode, neutre, typographie, forme, densité, élévation, mouvement, plate-forme, thème imbriqué à dix axes ;",
  "支持模板新增、删除和排序/分组规则移动。": "Prise en charge de l'ajout, de la suppression et du mouvement des règles de tri/regroupement de modèles.",
  "支持全选、反选、清除、可见项选择、Shift 区间、数量输出、批量栏显隐及行": "Prend en charge toutes les sélections, la sélection inverse, la sélection d'éléments clairs et visibles, l'intervalle de décalage, la sortie de quantité, l'affichage de la colonne de lots et l'affichage des lignes.",
  "支持网页与桌面": "Prise en charge Web et ordinateur de bureau",
  "支持选中/全部双向移动、两侧搜索、数量和 Empty 状态，以及 Ctrl/Command + 左右方向键。": "Supporte le mouvement bidirectionnel de sélection/tout, recherche des deux côtés, quantité et état vide, et touches fléchées Ctrl/Command + gauche et droite.",
