  "值、长文本和单项动作": "Valeurs, texte long et actions uniques",
  "值绑定、75 个事件与 7 个同步守卫": "Reliure de valeur, 75 événements et 7 caches de synchronisation",
  "只负责可拖动区域；按钮、链接、输入与菜单必须放进": "Uniquement responsable des zones déplaçables ; les boutons, liens, entrées et menus doivent être placés dans",
  "只复用主题": "Réutiliser uniquement les sujets",
