  "自动生成，覆盖每个源码模块、语义类、原始选择器、Token、自定义状态钩子、数据属性和关键帧；工具类使用下一节的专用完整清单。它是源码级目录，不是精选示例。": "Généré automatiquement, couvrant chaque module de code source, classe sémantique, sélecteur primitif, jeton, hook d'état personnalisé, attribut de données et image clé ; pour les classes d'outils, utilisez la liste complète dédiée dans la section suivante. Il s'agit d'un répertoire au niveau source, pas d'un exemple présenté.",
