  "作为父级。列宽类保持相同，AI 只需先确定父级系统。": "en tant que parent. La classe de largeur de colonne reste la même, l'IA n'a qu'à déterminer d'abord le système parent.",
  "作为兼容别名保留。按组件名构建时，构建器依据类选择器与": "Réservé comme alias compatible. Lors de la construction par nom de composant, le constructeur dépend du sélecteur de classe et",
  "作者可使用的 309 个属性被划分为上方行为契约中的 66 个行为入口、166 个结构/动作选择器和 77 个附加配置属性；另有 27 个由运行时维护的状态属性。状态属性可能同时作为初始配置读取，但作者可用的前三组彼此互斥，不会重复计数。": "Les 309 propriétés disponibles pour l'auteur sont divisées en 66 entrées de comportement dans le contrat de comportement ci-dessus, 166 sélecteurs de structure/action et 77 propriétés de configuration supplémentaires; il y a également 27 propriétés d'état maintenues par l'exécution. Les propriétés d'état peuvent être lues simultanément comme configuration initiale, mais les trois premiers ensembles disponibles pour l'auteur sont mutuellement exclusifs et ne sont pas comptés en double.",
