  "Axe 门禁阻断所选 WCAG A/AA 规则检测到的全部违规，不按 impact 降级放行，并输出规则、节点选择器、HTML 与修复摘要。自动化不能代替人工屏幕阅读器测试；正式产品仍应使用 NVDA / JAWS / VoiceOver 完成关键任务走查。": "Axe Gate bloque toutes les violations détectées par les règles WCAG A/AA sélectionnées, les passe sans dégradation par impact, et produit la règle, le sélecteur de noeuds, HTML, et le résumé de remise en état. L'automatisation ne peut remplacer les tests de lecture d'écrans humains; les produits de production devraient toujours utiliser NVDA/JAWS/VoiceOver pour les visites critiques.",
