  "Gardener": "Gardener",
  "Gardener — 为所有界面准备好的 CSS 基础设施": "Gardener — infrastructure CSS prête pour toutes les interfaces",
  "gardener / workspace / overview": "jardinier/espace de travail/survue",
  "Gardener 把基础 CSS、交互组件、业务配方、桌面端适配与机器可读清单放进同一套系统。人可以直接开发，AI 可以准确选用，无需每次重新组织样式。": "Gardener apporte des CSS de base, des composants interactifs, des recettes d'affaires, une adaptation de bureau et des manifestes lisibles par machine en un seul système. Les gens peuvent se développer directement, et l'IA peut sélectionner et utiliser avec précision sans avoir à réorganiser le style à chaque fois.",
  "Gardener 可以只使用 CSS，也可以加载零依赖运行时获得交互行为。完整包默认包含所有主题、组件和工具类。": "Gardener ne peut utiliser que CSS, ou charger un runtime de dépendance zéro pour un comportement interactif. Le paquet complet comprend tous les thèmes, composants et classes d'outils par défaut.",
  "Gardener 是面向人类开发者与 AI 页面生成器的通用 CSS、Vue 3、React、AngularJS 与 Blazor 组件、页面配方及桌面应用基础设施。": "Gardener est universel CSS, Vue 3, React, AngularJS et Blazor composants, recettes de page et infrastructure d'application de bureau pour les développeurs humains et les constructeurs de page AI.",
  "Gardener 首页": "Page d'accueil de Gardener",
  "Gardener 完整文档：CSS、Vue 3、React、AngularJS、Blazor、主题、Token、工具类、506 个组件、运行时、完整页面、AI 页面生成及桌面端适配。": "Gardener documentation complète: CSS, Vue 3, React, AngularJS, Blazor, thème, Token, classe d'outils, 506 composants, temps d'exécution, page complète, génération de page AI et adaptation de bureau.",
  "Gardener 为 AI 提供五层事实来源：公共 API 清单回答“允许使用什么稳定名称与入口”，能力清单回答“行业常规能力是否实现”，组件清单回答“有什么”，工具类清单回答“精确类名是什么”，配方清单回答“复杂页面怎样开始”。": "Gardener fournit cinq couches de sources de vérité pour l'IA : la liste publique des API répond « quels noms et entrées stables sont autorisés à être utilisés », la liste des capacités répond « si les capacités régulières de l'industrie sont mises en œuvre », la liste des composants répond « ce qui est là », la liste des classes d'outils répond « quel est le nom précis de la classe », et la liste des recettes répond « comment démarrer une page complexe ».",
  "Gardener 文档": "Gardener Documentation",
  "Gardener 移动端组件预览": "Aperçu des composants mobiles Gardener",
  "Gardener 以 24 栅格作为企业后台、CMS 和精细表单的主兼容协议，同时通过": "Gardener utilise 24 raster comme principal protocole compatible pour le backend d'entreprise, le CMS et les formulaires fins, tout en transmettant",
