  "Reduced Motion": "Mouvement réduit",
  "Reduced Motion 关闭 Drawer、Tree 与 Skip Link 过渡；Forced Colors 提供显式当前项轮廓；打印隐藏操作导航，保留 Breadcrumb、文档前后页与流程信息。": "Réduction du mouvement éteint les transitions de Tiroir, d'Arbre et de Lien de Saut; Couleurs forcées fournit des contours d'article courants explicites; impression cache la navigation de fonctionnement et conserve Fil d'Ariane, les pages avant et arrière des documents, et l'information de processus.",
  "Reduced Motion 降低保存动画；打印隐藏密码、清空、增删和提交动作，保留字段值、验证与审核信息。": "Reduce Motion réduit l'animation d'enregistrement; imprime les mots de passe cachés, efface, ajoute, supprime et soumet, en conservant les valeurs du champ, les données de vérification et de vérification.",
  "Reel": "Bobine",
  "Refund Status": "État du remboursement",
  "Registration": "Enregistrement",
  "Relation Picker": "Picker de relation",
  "Release 构建为 0 警告、0 错误；506 个组件全部经过真实静态 SSR。浏览器矩阵覆盖 Chromium、Firefox、WebKit、桌面与移动视口、键盘和 Axe WCAG A/AA；CI 强制 Firefox。 NuGet 使用隔离缓存真实发布消费应用，并验证静态 Web Assets endpoint manifest；另有独立 .NET 11 Preview 包消费者。程序集实测 343,552 B，43 个静态资源共 7,608,327 B，CSS gzip 139,269 B，runtime gzip 25,989 B，Blazor bridge gzip 2,054 B，nupkg 约 1.22 MiB、低于 6,000,000 B 硬上限；全部低于硬预算且 DLL/XML 可复现。": "Version de version avec 0 avertissement, 0 erreur ; 506 composants ont tous réussi le véritable SSR statique. Browser Matrix couvre Chromium, Firefox, WebKit, les fenêtres de bureau et mobiles, le clavier et Axe WCAG A/AA ; CI impose Firefox. NuGet utilise un cache isolé pour publier des applications grand public et valider les manifestes de points de terminaison statiques des actifs Web ; il existe également un consommateur de package .NET 11 Preview autonome. L'assemblage mesuré est de 343 552 B, 43 ressources statiques au total 7 608 327 B, CSS gzip 139 269 B, runtime gzip 25 989 B, Blazor bridge gzip 2 054 B, nupkg environ 1,22 Mio, en dessous de la limite stricte de 6 000 000 B ; le tout en dessous du budget strict et des DLL/XML reproductibles.",
  "Release confidence · 1.0.0": "Confiance de libération · 1.0.0",
  "Release-ready delivery · 1.0.0": "Livraison prête à la mainlevée · 1.0.0",
  "Repeatable Field": "Champ répétable",
