  "Tauri 与 Electron 共用标题栏、窗口控制、活动栏、编辑区、检查器、分栏与状态栏，桥接接口保持安全。": "Tauri et Electron partagent la barre de titre, le contrôle de la fenêtre, la barre d'activité, la zone d'édition, l'inspecteur, les colonnes et la barre d'état, et l'interface du pont reste sécuritaire.",
  "Tauri 与 Electron 入口相互隔离，均返回带": "Les entrées Tauri et Electron sont isolées l'une de l'autre et retournent toutes deux vers la ceinture",
  "Tauri v2": "Tauri v2",
  "Tauri v2 由应用注入 Window API；权限能力、文件系统、Updater、Deep Link、Tray 与多窗口按应用 Capability 配置，不由 CSS 自动申请。": "Tauri v2 est injecté dans l'API de la fenêtre par l'application; les capacités de permission, le système de fichiers, Updater, Deep Link, Tray et multi-window sont configurés en fonction de la capacité de l'application et ne sont pas automatiquement appliqués par CSS.",
  "Tauri/Electron 工作台主功能切换": "Interrupteur de la fonction principale de l'atelier Tauri/Electron",
  "Tauri/Electron 中可把 CRM、Project、Dashboard、Settings 和 Notification 根页放入": "Les pages racine CRM, Project, Dashboard, Paramètres et Notification peuvent être placées dans Tauri/Electron",
