  "Tenant Chooser": "Choisisseur de logements",
  "Thinking": "Penser",
  "Thinking 默认展示可读的推理摘要或进度，不要求泄露模型私有推理链；产品需明确区分“摘要”“工具日志”和“最终答案”。": "La pensée affiche un résumé de raisonnement lisible ou un progrès par défaut et n'exige pas que la chaîne de raisonnement privé modèle soit divulguée; le produit doit clairement distinguer entre « résumé », « journal d'outils » et « réponse finale ».",
